// AI dictionary: renders GLOSSARY_TERMS (content/glossary-*.js) A to Z with search, category filters,
// an A–Z jump bar and read aloud. Used by the dictionary page (glossary/index.html, both languages in
// the page, generated by scripts/build.js) and by the Learn section (one language, lesson links open
// inside the course). Works in Node too, so the build can generate the static page from the same code.
var Glossary = (function () {
  const CATS = {
    basics: ["AI basics", "AI basics"], ml: ["Machine learning", "Machine learning"], dl: ["Deep learning", "Deep learning"],
    llm: ["LLMs and GenAI", "LLMs aur GenAI"], agents: ["Agents and tools", "Agents aur tools"], data: ["Data", "Data"],
    mlops: ["MLOps and deployment", "MLOps aur deployment"], eval: ["Evaluation and safety", "Evaluation aur safety"], product: ["Product and career", "Product aur career"]
  };
  const UI = {
    search: ["Search terms, like RAG, overfitting or tokens", "Shabd dhoondho, jaise RAG, overfitting ya tokens"],
    all: ["All", "Sab"], meaning: ["In one line", "Ek line mein"], detail: ["Explained", "Vistaar se"], example: ["Example", "Example"],
    learn: ["Learn it", "Seekho"], related: ["Related", "Jude hue shabd"], also: ["Also called", "Ise yeh bhi kehte hain"],
    hear: ["Hear it", "Suno"], none: ["No matching terms. Try another word.", "Koi match nahi. Koi aur shabd try karo."],
    count: ["{n} terms", "{n} shabd"], open: ["Open all", "Sab kholo"], close: ["Close all", "Sab band karo"]
  };
  const esc = s => String(s ?? "").replace(/[&<>"']/g, c => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]));
  const slug = term => "term-" + term.toLowerCase().replace(/\(.*?\)/g, "").replace(/[^a-z0-9]+/g, "-").replace(/^-+|-+$/g, "");
  const base = s => s.replace(/\s*\(.*\)$/, "").toLowerCase();
  const letterOf = term => { const c = term.charAt(0).toUpperCase(); return /[A-Z]/.test(c) ? c : "#"; };

  function terms(list) {
    const src = list || (typeof GLOSSARY_TERMS !== "undefined" ? GLOSSARY_TERMS : []);
    return src.slice().sort((a, b) => a.term.localeCompare(b.term, "en", { sensitivity: "base" }));
  }
  // Find a term by its name, its short name ("LLM" for "LLM (large language model)") or an alias.
  function resolver(T) {
    const map = new Map();
    T.forEach(t => { map.set(t.term.toLowerCase(), t); map.set(base(t.term), t); });
    T.forEach(t => (t.aka || "").split(/,\s*/).filter(Boolean).forEach(a => { if (!map.has(a.toLowerCase())) map.set(a.toLowerCase(), t); }));
    return name => map.get(name.toLowerCase()) || map.get(base(name));
  }

  // lang: "en", "hi" or "both" (both languages in the page, shown by html.lang-hi).
  // lessonLink(id) returns the attributes for a link to a lesson; lessonName(id) its title pair.
  function html({ lang = "en", lessonLink, lessonName, list } = {}) {
    const T = terms(list);
    const find = resolver(T);
    const pick = pair => lang === "hi" ? pair[1] : pair[0];
    const txt = pair => lang === "both" ? `<span data-l="en">${esc(pair[0])}</span><span data-l="hi" lang="hi-Latn">${esc(pair[1])}</span>` : esc(pick(pair));
    const sayText = (t, pair) => lang === "both" ? `${t}. ${pair[0]}` : `${t}. ${pick(pair)}`;
    const letters = [...new Set(T.map(t => letterOf(t.term)))];
    const az = "ABCDEFGHIJKLMNOPQRSTUVWXYZ".split("");
    const ui = k => txt(UI[k]);
    return `<div class="gl" data-glossary data-lang="${lang}">
      <div class="gl-tools">
        <label class="gl-search"><span class="sr-only">${esc(UI.search[0])}</span>
          <input type="search" data-gl-search placeholder="${esc(lang === "hi" ? UI.search[1] : UI.search[0])}" data-ph-hi="${esc(UI.search[1])}" data-ph-en="${esc(UI.search[0])}" autocomplete="off"></label>
        <div class="gl-cats" role="group" aria-label="Categories">
          <button type="button" class="chip gl-cat active" data-gl-cat="">${ui("all")}</button>
          ${Object.keys(CATS).map(c => `<button type="button" class="chip gl-cat" data-gl-cat="${c}">${txt(CATS[c])}</button>`).join("")}
        </div>
        <nav class="gl-az" aria-label="A to Z">${az.map(L => letters.includes(L) ? `<a href="#gl-${L}" data-gl-letter="${L}">${L}</a>` : `<span aria-hidden="true">${L}</span>`).join("")}</nav>
        <p class="small muted gl-meta"><span data-gl-count>${esc(UI.count[lang === "hi" ? 1 : 0].replace("{n}", T.length))}</span> · <button type="button" class="link-btn small" data-gl-toggle>${ui("open")}</button></p>
      </div>
      <p class="muted" data-gl-none hidden>${ui("none")}</p>
      ${letters.map(L => `<section class="gl-letter" id="gl-${L}" data-gl-group="${L}">
        <h2 class="gl-letter-head">${L}</h2>
        ${T.filter(t => letterOf(t.term) === L).map(t => {
          // Words separated by single spaces, so search can match from the start of a word ("rag" ≠ "average").
          const search = " " + [t.term, t.aka, ...t.short, ...t.detail].join(" ").toLowerCase().replace(/[^a-z0-9₹%]+/g, " ").trim() + " ";
          const related = t.related.map(find).filter(Boolean).filter((r, i, a) => r !== t && a.indexOf(r) === i);
          return `<details class="gl-term" id="${slug(t.term)}" data-gl-cat-of="${t.cat}" data-gl-text="${esc(search)}">
          <summary><span class="gl-name">${esc(t.term)}</span><span class="gl-short">${txt(t.short)}</span></summary>
          <div class="gl-body">
            <p class="gl-tags"><span class="chip">${txt(CATS[t.cat])}</span>${t.aka ? ` <span class="small muted">${ui("also")}: ${esc(t.aka)}</span>` : ""}
              <button type="button" class="kid-hear gl-hear" data-say="${esc(sayText(t.term, t.detail))}" data-say-hi="${esc(`${t.term}. ${t.detail[1]}`)}" aria-label="${esc(UI.hear[0])}">🔊</button></p>
            <p class="gl-detail">${txt(t.detail)}</p>
            <p class="gl-example"><strong>💡 ${ui("example")}:</strong> ${txt(t.example)}</p>
            ${t.lessons.length && lessonLink ? `<p class="small">📖 <strong>${ui("learn")}:</strong> ${t.lessons.map(id => `<a ${lessonLink(id)}>${lessonName ? txt(lessonName(id)) : esc(id)}</a>`).join(" · ")}</p>` : ""}
            ${related.length ? `<p class="small">🔗 <strong>${ui("related")}:</strong> ${related.map(r => `<a href="#${slug(r.term)}" data-gl-jump="${slug(r.term)}">${esc(r.term)}</a>`).join(" · ")}</p>` : ""}
          </div>
        </details>`;
        }).join("\n")}
      </section>`).join("\n")}
    </div>`;
  }

  // Search, category filter, A–Z, open all, jump to related terms, read aloud.
  function enhance(root, { lang = "en" } = {}) {
    const box = root.querySelector("[data-glossary]");
    if (!box) return;
    const items = [...box.querySelectorAll(".gl-term")];
    const input = box.querySelector("[data-gl-search]");
    let cat = "";
    const apply = () => {
      const q = (input.value || "").trim().toLowerCase().replace(/[^a-z0-9₹%]+/g, " ").trim();
      const qs = q ? " " + q : "";
      let shown = 0;
      items.forEach(el => {
        const ok = (!cat || el.dataset.glCatOf === cat) && (!q || el.dataset.glText.includes(qs));
        el.hidden = !ok;
        if (ok) shown++;
        if (q && ok && el.querySelector(".gl-name").textContent.toLowerCase().startsWith(q)) el.open = true;
      });
      box.querySelectorAll("[data-gl-group]").forEach(g => { g.hidden = !g.querySelector(".gl-term:not([hidden])"); });
      const n = box.querySelector("[data-gl-count]");
      const hi = lang === "hi" || (lang === "both" && document.documentElement.classList.contains("lang-hi"));
      if (n) n.textContent = UI.count[hi ? 1 : 0].replace("{n}", shown);
      box.querySelector("[data-gl-none]").hidden = shown > 0;
    };
    input.addEventListener("input", apply);
    box.querySelectorAll("[data-gl-cat]").forEach(b => b.addEventListener("click", () => {
      cat = b.dataset.glCat;
      box.querySelectorAll("[data-gl-cat]").forEach(x => x.classList.toggle("active", x === b));
      apply();
    }));
    const open = id => {
      const el = box.querySelector(`#${CSS.escape(id)}`);
      if (!el) return;
      if (el.hidden) { input.value = ""; cat = ""; box.querySelectorAll("[data-gl-cat]").forEach((x, i) => x.classList.toggle("active", i === 0)); apply(); }
      el.open = true;
      el.scrollIntoView({ block: "start", behavior: "smooth" });
    };
    box.querySelectorAll("[data-gl-jump]").forEach(a => a.addEventListener("click", e => { e.preventDefault(); open(a.dataset.glJump); }));
    box.querySelectorAll("[data-gl-letter]").forEach(a => a.addEventListener("click", e => {
      e.preventDefault();
      const g = box.querySelector(`#gl-${a.dataset.glLetter}`);
      if (g) { if (g.hidden) { input.value = ""; cat = ""; apply(); } g.scrollIntoView({ block: "start", behavior: "smooth" }); }
    }));
    const toggle = box.querySelector("[data-gl-toggle]");
    toggle.addEventListener("click", () => {
      const anyClosed = items.some(el => !el.hidden && !el.open);
      items.forEach(el => { if (!el.hidden) el.open = anyClosed; });
      toggle.innerHTML = anyClosed ? (box.dataset.lang === "both" ? `<span data-l="en">${UI.close[0]}</span><span data-l="hi">${UI.close[1]}</span>` : esc(UI.close[lang === "hi" ? 1 : 0]))
        : (box.dataset.lang === "both" ? `<span data-l="en">${UI.open[0]}</span><span data-l="hi">${UI.open[1]}</span>` : esc(UI.open[lang === "hi" ? 1 : 0]));
    });
    box.querySelectorAll(".gl-hear").forEach(b => b.addEventListener("click", e => {
      e.preventDefault();
      const hi = lang === "hi" || document.documentElement.classList.contains("lang-hi");
      if (typeof LessonReader !== "undefined") LessonReader.say(hi ? b.dataset.sayHi : b.dataset.say, hi ? "hi" : "en");
    }));
    if (location.hash && location.hash.startsWith("#term-")) open(location.hash.slice(1));
  }

  return { html, enhance, terms, slug, CATS };
})();

if (typeof module !== "undefined" && module.exports) module.exports = { Glossary };

// Dictionary page: language switch (both languages are in the page) and interactions.
if (typeof document !== "undefined" && document.getElementById("glossaryPage")) {
  const root = document.getElementById("glossaryPage");
  const getLang = () => { try { return JSON.parse(localStorage.getItem("aipf:lang")) === "hi" ? "hi" : "en"; } catch (e) { return "en"; } };
  const setLang = l => {
    document.documentElement.classList.toggle("lang-hi", l === "hi");
    document.querySelectorAll("[data-site-lang]").forEach(b => { b.classList.toggle("active", b.dataset.siteLang === l); b.setAttribute("aria-pressed", b.dataset.siteLang === l); });
    const input = root.querySelector("[data-gl-search]");
    if (input) { input.placeholder = l === "hi" ? input.dataset.phHi : input.dataset.phEn; input.dispatchEvent(new Event("input")); }
  };
  setLang(getLang());
  document.querySelectorAll("[data-site-lang]").forEach(b => b.addEventListener("click", () => {
    try { localStorage.setItem("aipf:lang", JSON.stringify(b.dataset.siteLang)); } catch (e) { /* private mode */ }
    setLang(b.dataset.siteLang);
  }));
  Glossary.enhance(root, { lang: "both" });
  setLang(getLang());
}
